use std::{hint::black_box, time::Instant};
use lpm_registry::{PackageMetadata, VersionMetadata};
fn main() {
    let bytes = std::fs::read(std::env::args().nth(1).unwrap()).unwrap();
    let started = Instant::now();
    let mut count = 0;
    for _ in 0..30 {
        let metadata: PackageMetadata = serde_json::from_slice(black_box(&bytes)).unwrap();
        count = metadata.versions.len();
        black_box(metadata);
    }
    println!("versions={count} version_size={} total_us={}", std::mem::size_of::<VersionMetadata>(), started.elapsed().as_micros());
}

microbenchmark_sources.merge-probe.rs:
use std::{hint::black_box, time::Instant};
use lpm_resolver::{benchmark_merge_cached_package_info as merge, benchmark_parse_owned_metadata_to_cache_info as parse_full, benchmark_parse_owned_partial_metadata_to_cache_info as parse_partial};
fn main() {
    let metadata: lpm_registry::PackageMetadata = serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();
    let version = metadata.versions.keys().max().unwrap().clone();
    let mut partial = serde_json::from_str::<lpm_registry::PackageMetadata>(r#"{"name":"next"}"#).unwrap();
    partial.name = metadata.name.clone();
    partial.versions.insert(version.clone(), metadata.versions[&version].clone());
    let full = parse_full(metadata);
    let partial = parse_partial(partial);
    let start = Instant::now();
    for _ in 0..20 {
        let intermediate = merge(black_box(&full), black_box(&partial));
        black_box(merge(black_box(&intermediate), black_box(&full)));
    }
    println!("total_us={} versions={}", start.elapsed().as_micros(), full.versions.len());
}
